def solve(g):
    n,m=len(g),len(g[0])
    srows={i for i,r in enumerate(g) if len(set(r))==1}
    scols={j for j in range(m) if len({r[j] for r in g})==1}
    rb=[]; prev=0
    for s in sorted(srows)+[n]:
        if s>prev: rb.append((prev,s)); prev=s+1
    cb=[]; prev=0
    for s in sorted(scols)+[m]:
        if s>prev: cb.append((prev,s)); prev=s+1
    # band indices
    def bi(v,s): return sum(1 for x in s if x<v)
    # markers per color
    marks={}
    for r in range(n):
        if r in srows: continue
        for c in range(m):
            if c in scols: continue
            v=g[r][c]
            if v not in (0,) and v!=g[srows.max()] if False else True:
                pass
    # background = value on separator lines
    seg=g[list(srows)[0]][list(scols)[0]]
    for r in range(n):
        if r in srows: continue
        for c in range(m):
            if c in scols: continue
            v=g[r][c]
            if v!=seg:
                marks.setdefault(v,[]).append((r,c))
    out=[row[:] for row in g]
    br,bbc=rb,cb
    # pitches
    pr=bbr=0
    # vertical pitch = distance between band starts? use consecutive band origins
    origins_r=[a for a,b in rb]; origins_c=[a for a,b in cb]
    vr=origins_r[1]-origins_r[0] if len(origins_r)>1 else 0
    vc=origins_c[1]-origins_c[0] if len(origins_c)>1 else 0
    for v,cells in marks.items():
        cells.sort()
        if len(cells)<2: continue
        for (r1_,c1_),(r2_,c2_) in zip(cells,cells[1:]):
            if r1_==r2_:  # horizontal
                step=vc; lo,hi=min(c1_,c2_),max(c1_,c2_)
                for c in range(lo+step,hi,step):
                    rr=r1_
                    if rr not in srows and 0<=c<m and 0<=rr<n: out[rr][c]=v
            elif c1_==c2_:  # vertical
                step=vr; lo,hi=min(r1_,r2_),max(r1_,r2_)
                for r in range(lo+step,hi,step):
                    cc=c1_
                    if cc not in scols and 0<=r<n: out[r][cc]=v
            else:
